head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[p > M > hideModal]<br/>showModal() 메소드로 표시한 모달 레이어를 숨기고, 비활성화(disabled) 되었던 컴포넌트를 원래 상태로 복원합니다.",
    "validation" : [
        "showModal() 메소드로 표시한 모달 레이어를 숨겨야 합니다.",
        "비활성화(disabled) 되었던 컴포넌트를 원래 상태로 복원해야 합니다.",
        "활성화된 모달 레이어가 없는 상태이면 호출이 무시되어야 합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.target_input1_onfocus = function () {
    wf_body_bottom.getObj("scwin").setReturnValue("target_input1 onfocus 발생");
}

scwin.target_input2_onfocus = function () {
    wf_body_bottom.getObj("scwin").setReturnValue("target_input2 onfocus 발생");
}

scwin.target_btn1_onfocus = function () {
    wf_body_bottom.getObj("scwin").setReturnValue("target_btn1 onfocus 발생");
}

scwin.checkDisabledStatus = function (prefix) {
    var compIds = ["target_input1", "target_input2", "target_btn1"];
    var states = [];
    for (var i = 0; i < compIds.length; i++) {
        var comp = $p.getComponentById(compIds[i]);
        if (comp) {
            states.push(compIds[i] + "=" + comp.getDisabled());
        }
    }
    wf_body_bottom.getObj("scwin").setReturnValue(prefix + " disabled 상태 : " + states.join(", "));
}

scwin.btn_showModal_onclick = function () {
    $p.showModal([btn_hideModal.getID()]);

    wf_body_bottom.getObj("scwin").setReturnValue("showModal 실행 (btn_hideModal 만 활성 유지)");
    wf_body_bottom.getObj("scwin").setReturnValue("disabledList.length : " + WebSquare.layer.disabledList.length);

    setTimeout(function () {
        scwin.checkDisabledStatus("[showModal 후]");
    }, 500);
}



scwin.btn_hideModal_onclick = function () {
    var beforeLen = WebSquare.layer.disabledList.length;
    $p.hideModal();
    var afterLen = WebSquare.layer.disabledList.length;

    wf_body_bottom.getObj("scwin").setReturnValue("hideModal 실행");
    wf_body_bottom.getObj("scwin").setReturnValue("disabledList.length : " + beforeLen + " → " + afterLen + (beforeLen > afterLen ? " (모달 해제됨)" : " (변화 없음)"));

    setTimeout(function () {
        scwin.checkDisabledStatus("[hideModal 후]");
    }, 500);
}



scwin.btn_hideModal_noModal_onclick = function () {
    var beforeLen = WebSquare.layer.disabledList.length;
    $p.hideModal();
    var afterLen = WebSquare.layer.disabledList.length;

    wf_body_bottom.getObj("scwin").setReturnValue("hideModal 실행 (모달 없는 상태)");
    wf_body_bottom.getObj("scwin").setReturnValue("disabledList.length : " + beforeLen + " → " + afterLen + (beforeLen === 0 && afterLen === 0 ? " (무시됨)" : ""));
}
